// 3D molecular models from the 2D drawing — real conformer geometry, honestly
// labelled.
//
// The 3D structure is DERIVED FROM THE IDCODE (the canonical encoding that is
// this app's single source of truth for structures): the same idcode always
// yields the same conformer (fixed seed), so the dialog's interactive view and
// the pane's inserted figure can never disagree. Geometry is generated by
// OpenChemLib's ConformerGenerator and then minimised with the MMFF94s force
// field — a REAL published force field (Halgren, J. Comput. Chem. 1996), not
// an invented spring model. What this produces is ONE low-energy conformer,
// not "the" shape of the molecule — flexible molecules populate many — and
// every result says so in its caveats.
//
// Rendering follows the same share-the-decision-function rule as the geometry
// canvas: projectScene() produces one depth-sorted draw list, and BOTH the
// dialog's live canvas and the inserted SVG figure consume it. The painter and
// the emitter cannot drift.
//
// Element data are published values, per the "all data must be real" mandate:
//   - Colors: the standard CPK/Jmol element color set.
//   - Van der Waals radii: Bondi (J. Phys. Chem. 1964) where defined,
//     Mantina et al. (J. Phys. Chem. A 2009) for main-group elements Bondi
//     did not cover. Elements outside the table render at 2.00 Å in the
//     "unknown element" color, and the result's caveats NAME them.

import { Molecule, ConformerGenerator, ForceFieldMMFF94 } from "openchemlib/full";
import { rgroupLabels } from "./builder";

export interface Atom3d {
  /** Element symbol, e.g. "C". */
  el: string;
  atomicNo: number;
  x: number;
  y: number;
  z: number;
  isH: boolean;
}

export interface Bond3d {
  a: number;
  b: number;
  order: number;
}

export interface Mol3dModel {
  atoms: Atom3d[];
  bonds: Bond3d[];
  formula: string;
  /** Count of non-hydrogen atoms, for display. */
  heavyAtoms: number;
  caveats: string[];
}

export interface Mol3dError {
  error: string;
}

export function isMol3dError(r: Mol3dModel | Mol3dError): r is Mol3dError {
  return (r as Mol3dError).error !== undefined;
}

/** Conformer generation cost is driven by FLEXIBILITY, not size: a rigid
 *  120-atom ring system generates in seconds while a 120-carbon chain takes
 *  minutes. Both gates are enforced and both refusals name their limit — a
 *  task-pane dialog that blocks for minutes is a frozen Word, not an error.
 *  (Measured: 60-carbon chain ≈ 17 s, 120-carbon chain ≈ 228 s.) */
export const MOL3D_MAX_HEAVY = 80;
export const MOL3D_MAX_ROTATABLE = 12;

/** Seed ladder: the same idcode must always give the same conformer, in the
 *  dialog and in the pane's insert path alike — the FIRST seed whose conformer
 *  passes the stereo check wins, and the ladder is fixed, so the result is
 *  still deterministic. More than one seed exists because OCL's generator
 *  sometimes builds the WRONG DOUBLE-BOND GEOMETRY (cis-2-butene arrives
 *  trans at seed 42 but correct at 43 — found by the adversarial pass);
 *  every conformer is therefore VERIFIED against the input stereochemistry
 *  and flipped ones are discarded. */
export const MOL3D_SEEDS = [42, 43, 44, 45, 46, 47, 48, 49];

/** CPK/Jmol element colors. Colors and radii are SEPARATE tables on purpose:
 *  a color is a convention (Jmol publishes one for every element), while a
 *  van der Waals radius is a MEASUREMENT — an element can honestly have the
 *  first and not the second, and drawing an invented radius as if published
 *  would break the display contract. */
const ELEMENT_COLOR: Record<number, string> = {
  1: "#FFFFFF", 2: "#D9FFFF", 3: "#CC80FF", 4: "#C2FF00", 5: "#FFB5B5",
  6: "#909090", 7: "#3050F8", 8: "#FF0D0D", 9: "#90E050", 10: "#B3E3F5",
  11: "#AB5CF2", 12: "#8AFF00", 13: "#BFA6A6", 14: "#F0C8A0", 15: "#FF8000",
  16: "#FFFF30", 17: "#1FF01F", 18: "#80D1E3", 19: "#8F40D4", 20: "#3DFF00",
  22: "#BFC2C7", 24: "#8A99C7", 25: "#9C7AC7", 26: "#E06633", 27: "#F090A0",
  28: "#50D050", 29: "#C88033", 30: "#7D80B0", 31: "#C28F8F", 32: "#668F8F",
  33: "#BD80E3", 34: "#FFA100", 35: "#A62929", 36: "#5CB8D1", 37: "#702EB0",
  38: "#00FF00", 46: "#006985", 47: "#C0C0C0", 48: "#FFD98F", 49: "#A67573",
  50: "#668080", 51: "#9E63B5", 52: "#D47A00", 53: "#940094", 54: "#429EB0",
  55: "#57178F", 56: "#00C900", 78: "#D0D0E0", 79: "#FFD123", 80: "#B8B8D0",
  81: "#A6544D", 82: "#575961", 83: "#9E4FB5", 92: "#008FFF",
};

/** Published van der Waals radii in Å: Bondi 1964; (M) = Mantina 2009.
 *  Elements NOT in this table (including common transition metals — Bondi
 *  never assigned Fe, Ti, Cr, Mn, Co…) render at the generic 2.00 Å and the
 *  result's caveats NAME them; an invented value must never look measured. */
const ELEMENT_VDW: Record<number, number> = {
  1: 1.20, 2: 1.40, 3: 1.82, 4: 1.53, 5: 1.92, 6: 1.70, 7: 1.55, 8: 1.52,
  9: 1.47, 10: 1.54, 11: 2.27, 12: 1.73, 13: 1.84, 14: 2.10, 15: 1.80,
  16: 1.80, 17: 1.75, 18: 1.88, 19: 2.75, 20: 2.31, 28: 1.63, 29: 1.40,
  30: 1.39, 31: 1.87, 32: 2.11, 33: 1.85, 34: 1.90, 35: 1.85, 36: 2.02,
  37: 3.03, 38: 2.49, 46: 1.63, 47: 1.72, 48: 1.58, 49: 1.93, 50: 2.17,
  51: 2.06, 52: 2.06, 53: 1.98, 54: 2.16, 55: 3.43, 56: 2.68, 78: 1.75,
  79: 1.66, 80: 1.55, 81: 1.96, 82: 2.02, 83: 2.07, 92: 1.86,
};
const UNKNOWN_COLOR = "#FF1493"; // Jmol's default for elements outside the set
const UNKNOWN_VDW = 2.0;

export function elementColor(atomicNo: number): string {
  return ELEMENT_COLOR[atomicNo] ?? UNKNOWN_COLOR;
}

export function elementVdw(atomicNo: number): number {
  return ELEMENT_VDW[atomicNo] ?? UNKNOWN_VDW;
}

/**
 * Generates the 3D model for an idcode. Errors are named, never thrown:
 * generic structures, oversized molecules, and generator failures each say
 * exactly what stopped them.
 */
export function generate3d(idcode: string, coordinates?: string): Mol3dModel | Mol3dError {
  let mol: Molecule;
  try {
    mol = coordinates ? Molecule.fromIDCode(idcode, coordinates) : Molecule.fromIDCode(idcode);
  } catch (e) {
    return { error: `The structure could not be read: ${(e as Error).message}` };
  }
  if (mol.getAllAtoms() === 0) return { error: "The canvas is empty — draw a molecule first." };
  if (mol.isFragment() || rgroupLabels(mol).length > 0) {
    return {
      error:
        "A generic structure (R-groups or query features) has no single 3D form — " +
        "each concrete substituent gives a different geometry. Replace the R-groups " +
        "with real atoms to model it.",
    };
  }
  let heavy = 0;
  for (let i = 0; i < mol.getAllAtoms(); i++) if (mol.getAtomicNo(i) !== 1) heavy++;
  if (heavy > MOL3D_MAX_HEAVY) {
    return {
      error:
        `This molecule has ${heavy} non-hydrogen atoms; 3D conformer generation is limited to ` +
        `${MOL3D_MAX_HEAVY} so the canvas stays responsive. (Proteins and polymers belong in a ` +
        "dedicated modelling tool.)",
    };
  }
  const rotatable = mol.getRotatableBondCount();
  if (rotatable > MOL3D_MAX_ROTATABLE) {
    return {
      error:
        `This molecule has ${rotatable} rotatable bonds; 3D conformer generation is limited to ` +
        `${MOL3D_MAX_ROTATABLE} — flexibility, not size, is what makes the search explode, and a ` +
        "long chain can block this window for minutes.",
    };
  }
  const caveats: string[] = [];
  // Stereo verification baseline: the canonical input idcode, and the input
  // with all stereo stripped. A conformer is accepted only if re-perceiving
  // its 3D geometry gives back the input stereochemistry — OCL's generator
  // sometimes builds cis bonds trans, and a confidently wrong diastereomer
  // in a document is the worst possible output.
  const inputId = mol.getIDCode();
  const strippedRef = Molecule.fromIDCode(inputId);
  strippedRef.stripStereoInformation();
  const strippedId = strippedRef.getIDCode();
  const inputHasStereo = inputId !== strippedId;
  mol.addImplicitHydrogens();
  let conf: Molecule | null = null;
  let stereoNote: string | null = null;
  let genError = "";
  for (const seed of MOL3D_SEEDS) {
    let cand: Molecule | null = null;
    try {
      cand = new ConformerGenerator(seed).getOneConformerAsMolecule(mol);
    } catch (e) {
      genError = (e as Error).message;
      continue;
    }
    if (!cand || cand.getAllAtoms() === 0) continue;
    let minimised = true;
    try {
      new ForceFieldMMFF94(cand, "MMFF94s").minimise();
    } catch {
      minimised = false;
    }
    // Re-perceive stereo from the generated geometry (after minimisation —
    // it moves atoms too) and compare.
    const check = cand.getCompactCopy();
    check.removeExplicitHydrogens(true); // 3D coordinates — parities re-perceived from geometry
    const checkId = check.getIDCode();
    let accepted = false;
    if (checkId === inputId) {
      accepted = true; // stereochemistry preserved exactly
    } else if (!inputHasStereo) {
      // Strip stereo on a COORDINATE-FREE rebuild: with 3D coordinates still
      // attached, getIDCode re-perceives the parities from geometry and the
      // strip is silently undone (stereo verdicts flip on provenance).
      const checkStripped = Molecule.fromIDCode(checkId);
      checkStripped.stripStereoInformation();
      if (checkStripped.getIDCode() === strippedId) {
        accepted = true;
        stereoNote =
          "The drawing specifies no stereochemistry — the model shows ONE stereoisomer " +
          "(a 3D structure cannot stay undecided).";
      }
    }
    if (accepted) {
      conf = cand;
      caveats.push(
        minimised
          ? "One MMFF94s-minimised conformer is shown — a real low-energy shape, not the only one: " +
            "flexible molecules populate many conformers."
          : "MMFF94s could not parameterise this molecule (common for organometallics and charged " +
            "species) — the self-organised conformer is shown unminimised.",
      );
      if (stereoNote) caveats.push(stereoNote);
      break;
    }
  }
  if (!conf) {
    if (inputHasStereo) {
      return {
        error:
          "No conformer matching the DRAWN stereochemistry could be generated (the generator kept " +
          "producing the wrong double-bond or centre geometry, a known upstream limitation). " +
          "Nothing is shown rather than the wrong stereoisomer. Removing the stereo marks will " +
          "model the structure honestly as 'one stereoisomer shown'.",
      };
    }
    return {
      error: genError
        ? `No 3D conformer could be generated: ${genError}`
        : "No 3D conformer could be generated for this structure.",
    };
  }
  const atoms: Atom3d[] = [];
  const noRadius = new Set<string>();
  const noColor = new Set<string>();
  for (let i = 0; i < conf.getAllAtoms(); i++) {
    const atomicNo = conf.getAtomicNo(i);
    if (!ELEMENT_VDW[atomicNo]) noRadius.add(conf.getAtomLabel(i));
    if (!ELEMENT_COLOR[atomicNo]) noColor.add(conf.getAtomLabel(i));
    atoms.push({
      el: conf.getAtomLabel(i),
      atomicNo,
      x: conf.getAtomX(i),
      y: conf.getAtomY(i),
      z: conf.getAtomZ(i),
      isH: atomicNo === 1,
    });
  }
  const bonds: Bond3d[] = [];
  for (let i = 0; i < conf.getAllBonds(); i++) {
    bonds.push({ a: conf.getBondAtom(0, i), b: conf.getBondAtom(1, i), order: conf.getBondOrder(i) });
  }
  if (noRadius.size > 0) {
    caveats.push(
      `No published van der Waals radius (Bondi/Mantina) for: ${[...noRadius].sort().join(", ")} — ` +
      "drawn at a generic 2.00 Å, which matters most in the space-filling style.",
    );
  }
  if (noColor.size > 0) {
    caveats.push(`No CPK color assigned for: ${[...noColor].sort().join(", ")} — shown in the generic color.`);
  }
  let formula = "";
  try {
    formula = mol.getMolecularFormula().formula;
  } catch {
    // formula stays empty
  }
  return { atoms, bonds, formula, heavyAtoms: heavy, caveats };
}

// ---------------------------------------------------------------------------
// View state and projection
// ---------------------------------------------------------------------------

export type Mol3dStyle = "ballstick" | "stick" | "spacefill";

export interface Mol3dView {
  /** Row-major 3×3 rotation matrix. Kept orthonormal by rotateView. */
  rot: number[];
  /** 1 = fit to canvas. */
  zoom: number;
  showH: boolean;
  style: Mol3dStyle;
}

export function defaultMol3dView(): Mol3dView {
  return { rot: [1, 0, 0, 0, 1, 0, 0, 0, 1], zoom: 1, showH: true, style: "ballstick" };
}

const matMul = (a: number[], b: number[]): number[] => {
  const r = new Array(9).fill(0);
  for (let i = 0; i < 3; i++)
    for (let j = 0; j < 3; j++)
      for (let k = 0; k < 3; k++) r[3 * i + j] += a[3 * i + k] * b[3 * k + j];
  return r;
};

/** Gram–Schmidt re-orthonormalisation — hundreds of incremental drag rotations
 *  must not let the matrix drift into a shear. */
const orthonormalize = (m: number[]): number[] => {
  let u = [m[0], m[1], m[2]];
  const nu = Math.hypot(...u) || 1;
  u = u.map((v) => v / nu);
  let v = [m[3], m[4], m[5]];
  const du = v[0] * u[0] + v[1] * u[1] + v[2] * u[2];
  v = v.map((x, i) => x - du * u[i]);
  const nv = Math.hypot(...v) || 1;
  v = v.map((x) => x / nv);
  const w = [
    u[1] * v[2] - u[2] * v[1],
    u[2] * v[0] - u[0] * v[2],
    u[0] * v[1] - u[1] * v[0],
  ];
  return [...u, ...v, ...w];
};

/** Applies a drag of (dx, dy) pixels as rotations about the screen axes. */
export function rotateView(view: Mol3dView, dx: number, dy: number): Mol3dView {
  const ax = dy * 0.011; // vertical drag tips about the screen x-axis
  const ay = dx * 0.011; // horizontal drag spins about the screen y-axis
  const rx = [1, 0, 0, 0, Math.cos(ax), -Math.sin(ax), 0, Math.sin(ax), Math.cos(ax)];
  const ry = [Math.cos(ay), 0, Math.sin(ay), 0, 1, 0, -Math.sin(ay), 0, Math.cos(ay)];
  return { ...view, rot: orthonormalize(matMul(matMul(ry, rx), view.rot)) };
}

export interface SphereOp {
  kind: "sphere";
  x: number;
  y: number;
  r: number;
  color: string;
  depth: number;
}

export interface RodOp {
  kind: "rod";
  x1: number;
  y1: number;
  x2: number;
  y2: number;
  r: number;
  color: string;
  depth: number;
}

export type DrawOp = SphereOp | RodOp;

/** Visual radii in Å by style. Ball-and-stick balls at 30% vdW and rods of
 *  0.12 Å are the conventional proportions; spacefill is the full vdW sphere. */
const BALL_SCALE = 0.3;
const ROD_R_BALLSTICK = 0.12;
const ROD_R_STICK = 0.17;

function atomRadius(atomicNo: number, style: Mol3dStyle): number {
  if (style === "spacefill") return elementVdw(atomicNo);
  if (style === "stick") return ROD_R_STICK;
  return elementVdw(atomicNo) * BALL_SCALE;
}

/**
 * Projects the model into one depth-sorted draw list (far → near) for a
 * w × h canvas. Orthographic projection — perspective adds nothing legible at
 * molecule scale and would make the inserted figure disagree with rulers.
 */
export function projectScene(model: Mol3dModel, view: Mol3dView, w: number, h: number): DrawOp[] {
  const keep = model.atoms.map((a) => view.showH ? true : !a.isH);
  const R = view.rot;
  const pts = model.atoms.map((a) => ({
    x: R[0] * a.x + R[1] * a.y + R[2] * a.z,
    y: R[3] * a.x + R[4] * a.y + R[5] * a.z,
    z: R[6] * a.x + R[7] * a.y + R[8] * a.z,
  }));
  // Fit: bounding radius of the VISIBLE scene including sphere radii, about
  // the visible centroid — a hidden hydrogen shell must not shrink the fit.
  let cx = 0, cy = 0, n = 0;
  pts.forEach((p, i) => { if (keep[i]) { cx += p.x; cy += p.y; n++; } });
  if (n === 0) return [];
  cx /= n; cy /= n;
  let bound = 0.1;
  pts.forEach((p, i) => {
    if (!keep[i]) return;
    const rr = atomRadius(model.atoms[i].atomicNo, view.style);
    bound = Math.max(bound, Math.hypot(p.x - cx, p.y - cy) + rr);
  });
  const scale = (Math.min(w, h) / 2) * 0.92 * view.zoom / bound;
  const px = (i: number): [number, number] => [
    w / 2 + (pts[i].x - cx) * scale,
    h / 2 - (pts[i].y - cy) * scale,
  ];
  const ops: DrawOp[] = [];
  for (let i = 0; i < model.atoms.length; i++) {
    if (!keep[i]) continue;
    const [x, y] = px(i);
    ops.push({
      kind: "sphere",
      x, y,
      r: atomRadius(model.atoms[i].atomicNo, view.style) * scale,
      color: elementColor(model.atoms[i].atomicNo),
      depth: pts[i].z,
    });
  }
  if (view.style !== "spacefill") {
    const rodR = (view.style === "stick" ? ROD_R_STICK : ROD_R_BALLSTICK) * scale;
    for (const b of model.bonds) {
      if (!keep[b.a] || !keep[b.b]) continue;
      const [x1, y1] = px(b.a);
      const [x2, y2] = px(b.b);
      const mx = (x1 + x2) / 2, my = (y1 + y2) / 2;
      const mz = (pts[b.a].z + pts[b.b].z) / 2;
      // Each half-rod wears its atom's color and sits at the depth of its own
      // half, so a bond correctly threads in front of some atoms and behind
      // others.
      ops.push({
        kind: "rod", x1, y1, x2: mx, y2: my, r: rodR,
        color: elementColor(model.atoms[b.a].atomicNo),
        depth: (pts[b.a].z + mz) / 2,
      });
      ops.push({
        kind: "rod", x1: mx, y1: my, x2, y2, r: rodR,
        color: elementColor(model.atoms[b.b].atomicNo),
        depth: (pts[b.b].z + mz) / 2,
      });
    }
  }
  ops.sort((p, q) => p.depth - q.depth);
  return ops;
}

// ---------------------------------------------------------------------------
// Painters — one draw list, two surfaces
// ---------------------------------------------------------------------------

const shade = (hex: string, f: number): string => {
  const v = parseInt(hex.slice(1), 16);
  const c = (x: number): number => Math.max(0, Math.min(255, Math.round(x * f)));
  const r = c((v >> 16) & 255), g = c((v >> 8) & 255), b = c(v & 255);
  return `#${((1 << 24) | (r << 16) | (g << 8) | b).toString(16).slice(1)}`;
};

/** Paints the ops onto a 2D canvas context (the dialog's live view). */
export function paintOps(ctx: CanvasRenderingContext2D, ops: DrawOp[], w: number, h: number): void {
  ctx.clearRect(0, 0, w, h);
  for (const op of ops) {
    if (op.kind === "rod") {
      ctx.strokeStyle = op.color;
      ctx.lineWidth = op.r * 2;
      ctx.lineCap = "round";
      ctx.beginPath();
      ctx.moveTo(op.x1, op.y1);
      ctx.lineTo(op.x2, op.y2);
      ctx.stroke();
      // A darker seam along the lower edge keeps depth readable on white.
      ctx.strokeStyle = shade(op.color, 0.75);
      ctx.lineWidth = Math.max(1, op.r * 0.35);
      ctx.stroke();
    } else {
      const g = ctx.createRadialGradient(
        op.x - op.r * 0.35, op.y - op.r * 0.35, op.r * 0.1,
        op.x, op.y, op.r,
      );
      g.addColorStop(0, shade(op.color, 1.35));
      g.addColorStop(0.7, op.color);
      g.addColorStop(1, shade(op.color, 0.62));
      ctx.fillStyle = g;
      ctx.beginPath();
      ctx.arc(op.x, op.y, op.r, 0, 2 * Math.PI);
      ctx.fill();
    }
  }
}

/** "C6H12O6" → "C₆H₁₂O₆" — the display contract holds inside figures too. */
export function formulaSubscripts(formula: string): string {
  const SUB = "₀₁₂₃₄₅₆₇₈₉";
  return formula.replace(/(?<=[A-Za-z)\]\d])\d/g, (d) => SUB[Number(d)]);
}

const esc = (s: string): string =>
  s.replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;");

/** Emits the SAME ops as a standalone SVG (the insert path). White ground —
 *  this is a figure for a printed page, not a screenshot of a dark app. The
 *  caption states what the figure IS (formula, style, MMFF94s conformer) so
 *  the honesty travels with the picture. */
export function opsToSvg(ops: DrawOp[], w: number, h: number, caption?: string): string {
  const grads = new Map<string, string>();
  for (const op of ops) {
    if (op.kind === "sphere" && !grads.has(op.color)) {
      grads.set(op.color, `g${grads.size}`);
    }
  }
  const defs = [...grads.entries()]
    .map(([color, id]) =>
      `<radialGradient id="${id}" cx="0.35" cy="0.35" r="0.9">` +
      `<stop offset="0" stop-color="${shade(color, 1.35)}"/>` +
      `<stop offset="0.7" stop-color="${color}"/>` +
      `<stop offset="1" stop-color="${shade(color, 0.62)}"/>` +
      `</radialGradient>`)
    .join("");
  const body = ops
    .map((op) => {
      if (op.kind === "rod") {
        const f = (v: number): string => v.toFixed(2);
        return (
          `<line x1="${f(op.x1)}" y1="${f(op.y1)}" x2="${f(op.x2)}" y2="${f(op.y2)}" ` +
          `stroke="${op.color}" stroke-width="${f(op.r * 2)}" stroke-linecap="round"/>`
        );
      }
      const f = (v: number): string => v.toFixed(2);
      return `<circle cx="${f(op.x)}" cy="${f(op.y)}" r="${f(op.r)}" fill="url(#${grads.get(op.color)})"/>`;
    })
    .join("");
  const cap = caption
    ? `<text x="10" y="${h - 10}" font-family="Segoe UI, sans-serif" font-size="13" fill="#444">${esc(caption)}</text>`
    : "";
  return (
    `<svg xmlns="http://www.w3.org/2000/svg" width="${w}" height="${h}" viewBox="0 0 ${w} ${h}">` +
    `<defs>${defs}</defs><rect width="${w}" height="${h}" fill="#ffffff"/>${body}${cap}</svg>`
  );
}
